css:
@import url('https://fonts.googleapis.com/css2?family=Oxanium:wght@500;600;700;800&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=JetBrains+Mono:wght@400;500;700&display=swap');

/* ============ MOLTEN · Bare Metal — base tokens + shared helpers ============
   Full-trust theme, so custom properties, @keyframes, @media and backdrop-filter
   all survive the sanitizer and every value below can be a token. */
/* ---- Recolour contract ----
   Every warm value resolves through these tokens, so a sibling theme re-skins all
   14 surfaces by overriding this block alone. Overriding sheets are PREPENDED and
   need `:root:root` to win. The boot loader is exempt — it paints before this sheet
   exists and keeps its own copy of the ramp. */
:root{
  --mlt-font-display:'Oxanium','Segoe UI',system-ui,sans-serif;
  --mlt-font-body:'IBM Plex Sans','Segoe UI',system-ui,sans-serif;
  --mlt-font-mono:'JetBrains Mono',Consolas,monospace;
  /* Own slot so a sibling changes brand type without owning the topbar/drawer rows
     (brand TEXT comes from Branding.Title/Subtitle, so those rows stay shared too) */
  --mlt-font-brand:var(--mlt-font-display);
  --mlt-brand-weight:800;

  /* warm ramp, light -> deep */
  --mlt-ember-hi:#ffd9a1;          /* seam highlight */
  --mlt-ember-1:#ffb347;
  --mlt-ember-mid:#ff9d2e;         /* seam mid stop */
  --mlt-ember-2:#ff7a2e;           /* CORE — the theme's one identity colour */
  --mlt-ember-3:#ff4d24;
  /* rgb triplets — the alpha washes and glows need channels, not a hex */
  --mlt-ember-rgb:255,122,46;      /* = ember-2 */
  --mlt-ember-hot-rgb:255,102,26;  /* the big corner radials run hotter */
  --mlt-ember-shade-rgb:120,30,0;  /* inset shadow under raised ember surfaces */
  --mlt-counter-rgb:90,169,230;    /* cool counter-glow, opposite corner */
  --mlt-ink-on-ember:#221004;      /* ink that sits ON the molten gradient */
  --mlt-ink-bright:#f3eee8;        /* bright ink on the dark backdrop (login hero) */
  --mlt-backdrop:linear-gradient(160deg,#101318 0%,#0b0d11 55%,#0d0a08 100%);

  --mlt-radius:14px;
  --mlt-seam-h:linear-gradient(90deg,transparent,var(--mlt-ember-mid) 18%,var(--mlt-ember-hi) 50%,var(--mlt-ember-2) 82%,transparent);
  --mlt-seam-v:linear-gradient(180deg,var(--mlt-ember-1),var(--mlt-ember-2) 55%,var(--mlt-ember-3));
  --mlt-molten:linear-gradient(135deg,var(--mlt-ember-1) 0%,var(--mlt-ember-2) 48%,var(--mlt-ember-3) 100%);
}

/* ---- Status-reactive forge (data-tca-status on <html>) ----
   One lever, --tca-cool: 0 hot → 1 cold, and every warm colour mixes against it, so retuning
   the theme is one number. Registered so it animates; --tca-* so it survives sanitizing.
   Status is page-wide, so the cooling follows the user into Console / Files.
   Power buttons are NOT cooled — Start is what you want when everything else has gone cold. */
@property --tca-cool{syntax:'<number>';inherits:true;initial-value:0}
:root{
  --tca-ash:#5b6472;                      /* dead metal */
  --tca-cool:0;
  --tca-ember-now:color-mix(in srgb, var(--tca-ash) calc(var(--tca-cool) * 100%), var(--mlt-ember-2));
  --tca-glow-now:calc(1 - var(--tca-cool) * .75);
  transition:--tca-cool 1s ease;
}
html[data-tca-status="stopped"]{--tca-cool:1}
/* Transitional states keep some heat — lit, but not up to temperature. */
html[data-tca-status="starting"],
html[data-tca-status="stopping"]{--tca-cool:.5}

/* ---- Restyling the compiled tokens: details, advanced-actions, docker ports ----
   Everything below goes through data-tca-component / data-part / data-kind and never a
   .mud-* class, so a MudBlazor upgrade can't silently unstyle it (contract:
   docs/LAYOUT_TEMPLATE_EXTENSIONS.md §3). Global, not per-surface — both service homes
   render these identically. */

/* Service details → a forge spec sheet. `td` is safe: the component owns those cells.
   height:auto undoes its .mud-height-full, which inside a fixed-height stage makes the card
   exactly pane-tall so overflow:hidden eats the rest — silently, since the scrolling parent
   sees a child that fits. Sizing to content hands the overflow back to the pane. */
[data-tca-component="service-details"]{background:transparent!important;border:1px solid var(--mud-palette-lines-default);
  border-radius:var(--mlt-radius);overflow:hidden;height:auto}
[data-tca-component="service-details"] [data-part="icon"]{display:none}     /* stock Mud row icons */
[data-tca-component="service-details"] [data-part="row"] td{
  border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06);padding:9px 16px;vertical-align:middle}
[data-tca-component="service-details"] [data-part="row"]:last-child td{border-bottom:none}
[data-tca-component="service-details"] [data-part="row"] td:first-child{width:196px;
  background:rgba(var(--mud-palette-text-primary-rgb),.02)}
[data-tca-component="service-details"] [data-part="label"]{font-family:var(--mlt-font-mono);
  font-size:.6rem;letter-spacing:.17em;text-transform:uppercase;opacity:.5}
[data-tca-component="service-details"] [data-part="value"]{font-family:var(--mlt-font-display);
  font-weight:600;font-size:.95rem;letter-spacing:.01em}
[data-tca-component="service-details"] [data-part="media"]{border-radius:6px;
  box-shadow:0 2px 8px rgba(0,0,0,.3)}

/* Phones: the 196px label column leaves ~190px of value, so every port chip takes its own line.
   Stack label above value (tr/td → block) and the chips get full width and wrap. */
@media (max-width:599.98px){
  [data-tca-component="service-details"] [data-part="row"],
  [data-tca-component="service-details"] [data-part="row"] td{display:block}
  [data-tca-component="service-details"] [data-part="row"]{
    border-bottom:1px solid rgba(var(--mud-palette-text-primary-rgb),.06)}
  [data-tca-component="service-details"] [data-part="row"]:last-child{border-bottom:none}
  [data-tca-component="service-details"] [data-part="row"] td{border-bottom:none;padding:0 14px}
  [data-tca-component="service-details"] [data-part="row"] td:first-child{
    width:auto;background:transparent;padding-top:9px}
  [data-tca-component="service-details"] [data-part="row"] td:last-child{padding-bottom:10px}
  /* the chips are the whole point — flow, don't stack */
  [data-tca-component="service-details"] [data-part="row"] td:last-child [data-part="value"]{
    display:flex;flex-wrap:wrap;gap:7px;align-items:center}
}

/* Advanced actions → a grid of forge levers. data-kind is the only stable handle: which buttons
   render depends on the viewer's permissions, so nothing positional survives a sub-user. */
[data-tca-component="service-advanced-actions"]{background:transparent!important}
[data-tca-component="service-advanced-actions"] [data-part="list"]{display:grid;
  grid-template-columns:repeat(auto-fill,minmax(216px,1fr));gap:10px}
[data-tca-component="service-advanced-actions"] [data-part="item"]{display:block}
[data-tca-component="service-advanced-actions"] [data-part="item"] td{display:block;padding:0;border:none}
[data-tca-component="service-advanced-actions"] [data-part="action"]{width:100%;height:46px;
  justify-content:flex-start;gap:10px;padding:0 15px;border-radius:11px;
  border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, rgba(255,255,255,.03), transparent 60%), rgba(var(--mud-palette-surface-rgb),.7);
  font-family:var(--mlt-font-display);font-size:.76rem;font-weight:600;letter-spacing:.09em;
  text-transform:uppercase;color:var(--mud-palette-text-primary);
  transition:border-color .15s, background .15s, transform .1s}
/* Hover rides the stationary item wrapper, not the button — a translateY on the button's own
   :hover makes it flee a cursor arriving from below, and vibrate. currentColor, not primary:
   an orange film over a warning/error button (Repair, Delete) reads as mud. */
[data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"]{transform:translateY(-1px);
  background:color-mix(in srgb, currentColor 10%, transparent)}
[data-tca-component="service-advanced-actions"] [data-part="action"]:active{transform:translateY(0)}
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="settings"]{
  border-color:color-mix(in srgb, var(--mlt-ember-2) 45%, transparent);color:var(--mlt-ember-1)}
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="reinstall"],
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="repair"]{
  border-color:color-mix(in srgb, var(--mud-palette-warning) 45%, transparent);color:var(--mud-palette-warning)}
/* The one action that can't be undone reads that way */
[data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"]{
  border-color:color-mix(in srgb, var(--mud-palette-error) 55%, transparent);color:var(--mud-palette-error);
  background:linear-gradient(180deg, color-mix(in srgb, var(--mud-palette-error) 9%, transparent), transparent 70%)}
[data-tca-component="service-advanced-actions"] [data-part="item"]:hover [data-part="action"][data-kind="delete"]{
  background:color-mix(in srgb, var(--mud-palette-error) 16%, transparent)}

/* Docker ports → the bare address gets a label; chips become forge tags that cool */
[data-tca-component="docker-ports"] [data-part="value"][data-kind="address"]{
  display:inline-flex;align-items:center;gap:10px;font-family:var(--mlt-font-mono);
  font-size:.92rem;letter-spacing:.06em}
[data-tca-component="docker-ports"] [data-part="value"][data-kind="address"]::before{content:"NODE";
  font-size:.55rem;letter-spacing:.2em;opacity:.5;padding:3px 7px;border-radius:5px;
  border:1px solid var(--mud-palette-lines-default)}
[data-tca-component="docker-ports"] [data-part="item"][data-kind="port"],
[data-tca-component="service-details"] [data-part="item"][data-kind="port"]{
  font-family:var(--mlt-font-mono)!important;font-size:.7rem;letter-spacing:.05em;border-radius:7px;
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 45%, transparent)!important;
  background:color-mix(in srgb, var(--tca-ember-now) 10%, transparent)!important;
  color:var(--mud-palette-text-primary)!important}
[data-tca-component="docker-ports"] [data-part="item"][data-kind="more"]{
  font-family:var(--mlt-font-mono);font-size:.68rem;opacity:.55}

/* ---- Global typography swap (the single biggest de-branding lever) ---- */
body,.mud-typography,.mud-input,.mud-input *,.mud-select,.mud-menu-list,.mud-list,
.mud-table,.mud-button-root:not(.mud-fab),.mud-chip,.mud-tooltip,.mud-alert,.mud-breadcrumbs{
  font-family:var(--mlt-font-body);
}
.mud-typography-h1,.mud-typography-h2,.mud-typography-h3,.mud-typography-h4,
.mud-typography-h5,.mud-typography-h6,.mud-dialog-title,.mud-card-header .mud-typography{
  font-family:var(--mlt-font-display);
  letter-spacing:.015em;
}
code,kbd,pre,.mud-code,.xterm{font-family:var(--mlt-font-mono)}

/* ---- Molten seam utility ---- */
.mlt-seam{height:2px;border-radius:2px;background:var(--mlt-seam-h);background-size:220% 100%;
  animation:mlt-flow 9s linear infinite;opacity:.9}
.mlt-mono{font-family:var(--mlt-font-mono);letter-spacing:.14em;text-transform:uppercase}

/* Every routed page hugs the seam (!important — Mud's mt-4 / pa-2 utilities are too) */
.mlt-bc ~ .mud-container{margin-top:4px!important;padding-top:0!important}

/* Connection dot (footer dock + topbar LINK pill): the inline-block tooltip wrapper reserves
   descender space under the 20px SVG, floating the dot ~2.5px high */
.mlt-ft__link .mud-tooltip-root,.mlt-tbe__pill .mud-tooltip-root{display:flex;align-items:center;line-height:0}
/* Same baseline strut on the service-icon atom in the header chip */
.mlt-svh__chip .tca-service-icon{display:flex;align-items:center;justify-content:center;line-height:0}

/* ---- Ingot brand chip (shared by topbar / drawer / login) ---- */
.mlt-ingot{display:inline-flex;align-items:center;justify-content:center;flex:none;
  width:34px;height:34px;border-radius:9px;color:var(--mlt-ink-on-ember);font-size:16px;
  background:var(--mlt-molten);
  box-shadow:0 3px 12px rgba(var(--mlt-ember-rgb),.45),inset 0 1px 0 rgba(255,255,255,.5),inset 0 -2px 4px rgba(var(--mlt-ember-shade-rgb),.35)}
.mlt-ingot--lg{width:42px;height:42px;border-radius:11px;font-size:20px}

/* ---- Scrollbars ---- */
*::-webkit-scrollbar{width:10px;height:10px}
*::-webkit-scrollbar-track{background:transparent}
*::-webkit-scrollbar-thumb{background:rgba(var(--mud-palette-text-primary-rgb),.14);border-radius:8px;
  border:2px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-thumb:hover{background:rgba(var(--mud-palette-primary-rgb),.45);border:2px solid transparent;background-clip:content-box}

/* ---- Keyframes + reduced motion ---- */
@keyframes mlt-flow{0%{background-position:0% 0}100%{background-position:220% 0}}
@keyframes mlt-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes mlt-glow{0%,100%{box-shadow:0 0 22px rgba(var(--mlt-ember-rgb),.35)}50%{box-shadow:0 0 34px rgba(var(--mlt-ember-rgb),.6)}}
/* Stop the loops outright — the `animation-duration:.001s` trick makes them strobe */
@media (prefers-reduced-motion: reduce){
  .mlt-seam,.mlt-svh__seam,.mlt-login__brand::after,.mlx__orb,
  .mlt-login__brand-inner,.mlt-login__card{animation:none!important}
  /* the forge still cools — it just arrives there instead of fading */
  :root{transition:none}
}

contents.content:
{% comment %} MOLTEN · DockerService.Header surface — icon chip, live name, blueprint line and
per-action power buttons, all built from atom tokens (LAYOUT_TEMPLATE_EXTENSIONS.md §1b).
{% endcomment %}
<div class="mlt-svh mlt-svh--atoms">
  <div class="mlt-svh__lockup">
    <span class="mlt-svh__chip">{% component "service-icon" %}</span>
    <div class="mlt-svh__stack">
      <span class="mlt-svh__name">{% component "live-name" %}</span>
      <span class="mlt-svh__ident mlt-mono">{{ Service.BlueprintName }}{% if Service.Image %} // {{ Service.Image }}{% if Service.Tag %}:{{ Service.Tag }}{% endif %}{% endif %}</span>
    </div>
  </div>
  {% if Permissions.Control %}
  <div class="mlt-svh__power">
    {% component "power-start" %}
    {% component "power-restart" %}
    {% component "power-stop" %}
    {% component "power-kill" %}
  </div>
  {% endif %}
</div>
<div class="mlt-svh__seam"></div>

contents.css:
.mud-container:has(> .mlt-svh){margin-top:4px!important;padding-top:0!important}
.mlt-svh{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:0 2px}

/* lockup: icon chip + live name + identity line */
.mlt-svh__lockup{display:flex;align-items:center;gap:14px;flex:1 1 300px;min-width:0}
.mlt-svh__chip{
  width:46px;height:46px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:12px;
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 32%, transparent);
  color:var(--tca-ember-now);
  background:linear-gradient(160deg, color-mix(in srgb, var(--tca-ember-now) 14%, transparent),
                                     color-mix(in srgb, var(--tca-ember-now) 4%, transparent));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.mlt-svh__stack{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlt-svh__name .tca-live-name{
  font-family:var(--mlt-font-display);font-weight:700;font-size:clamp(1.35rem,2.1vw,1.8rem);
  line-height:1.1;letter-spacing:.015em;display:block;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.mlt-svh__ident{font-size:.64rem;opacity:.55;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* connection cards: author chrome around the chrome-less address atoms */
.mlt-svh__conns{gap:10px;align-items:stretch;min-width:0}
.mlt-svh__conncard{
  display:flex;flex-direction:column;gap:3px;justify-content:center;
  padding:7px 12px;border-radius:10px;min-width:0;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-surface-rgb),.55);
}
.mlt-svh__connlabel{font-size:.55rem;opacity:.5}
.tca-conn{font-family:var(--mlt-font-mono);font-size:.74rem;display:inline-flex;align-items:center;
  gap:2px;white-space:nowrap}
.tca-conn .mud-icon-button{padding:2px;margin-left:2px}

/* per-action power buttons (chrome-less <button> atoms styled from scratch) */
.mlt-svh__power{display:flex;align-items:center;gap:10px;margin-left:auto;flex-wrap:wrap}
.tca-power{
  display:inline-flex;align-items:center;gap:9px;height:40px;padding:0 18px;border-radius:11px;
  font-family:var(--mlt-font-display);font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  font-size:.78rem;border:1px solid transparent;cursor:pointer;background:transparent;color:inherit;
  transition:filter .15s, box-shadow .15s, transform .12s, background .15s;
}
.tca-power:active{transform:translateY(1px)}
.tca-power:disabled{opacity:.45;cursor:default}
.tca-power__icon{font-size:.72rem}
.tca-power-start{
  background:var(--mlt-molten);color:var(--mlt-ink-on-ember);
  box-shadow:0 4px 16px rgba(var(--mlt-ember-rgb),.32), inset 0 1px 0 rgba(255,255,255,.38);
}
.tca-power-start:hover:not(:disabled){filter:brightness(1.07);box-shadow:0 6px 22px rgba(var(--mlt-ember-rgb),.5)}
.tca-power-restart{border-color:color-mix(in srgb, var(--mud-palette-warning) 55%, transparent);color:var(--mud-palette-warning)}
.tca-power-restart:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-warning) 12%, transparent)}
.tca-power-stop{border-color:color-mix(in srgb, var(--mud-palette-error) 55%, transparent);color:var(--mud-palette-error)}
.tca-power-stop:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-error) 12%, transparent)}
.tca-power-kill{background:var(--mud-palette-error);color:#fff;box-shadow:0 4px 14px color-mix(in srgb, var(--mud-palette-error) 45%, transparent)}
.tca-power-kill:hover:not(:disabled){filter:brightness(1.08)}

/* Seam + chip follow the forge. The header renders on EVERY page, so this is what carries the
   status cue into Console / Files / Scheduled Tasks. */
.mlt-svh__seam{height:2px;border-radius:2px;margin:12px 2px 18px;
  opacity:calc(.85 * var(--tca-glow-now));
  background:linear-gradient(90deg,transparent,var(--tca-ember-now) 18%,
             color-mix(in srgb, var(--tca-ember-now) 45%, #fff) 50%, var(--tca-ember-now) 82%,transparent);
  background-size:220% 100%;animation:mlt-flow 30s linear infinite}

@media (max-width:959.98px){
  /* mirror of the game header's phone tightening — power stays on the name's line */
  .mlt-svh{gap:12px;flex-wrap:nowrap}
  .mlt-svh__lockup{flex:1 1 auto;gap:10px}
  .mlt-svh__power{margin-left:auto;width:auto;flex:none;flex-wrap:nowrap;gap:8px}
  .tca-power{height:36px;padding:0 14px;font-size:.72rem}
  .mlt-svh__chip{width:40px;height:40px;border-radius:10px}
  .mlt-svh__seam{margin:10px 2px 12px}
}
@media (max-width:599.98px){
  .tca-power__label{display:none}
  .tca-power{padding:0 12px;gap:0}
  .tca-power__icon{font-size:.85rem}
}

.mlx{display:flex;flex-direction:column;gap:16px}

/* Telemetry band — same author-owned pattern as the game home */
.mlx__band{
  display:flex;align-items:stretch;gap:28px;flex-wrap:wrap;
  padding:16px 22px;border-radius:var(--mlt-radius);
  border:1px solid var(--mud-palette-lines-default);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
  position:relative;overflow:hidden;isolation:isolate;
}
/* No art window here: docker pages render NO .img-bg at all (the hero is game-only), so masking
   would reveal nothing — the ports block fills that space instead. Fill stays on ::before purely
   to keep both home surfaces structurally identical. */
.mlx__band::before{content:"";position:absolute;inset:0;z-index:-1;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--tca-ember-now) 8%, transparent), transparent 45%),
    rgba(var(--mud-palette-surface-rgb),.94)}
/* The ember seam under the band is the loudest heat cue — it drains to ash when the forge is out. */
.mlx__band::after{content:"";position:absolute;left:0;right:55%;bottom:0;height:2px;
  background:linear-gradient(90deg,var(--tca-ember-now),color-mix(in srgb, var(--tca-ember-now) 45%, #fff) 45%,transparent);
  opacity:calc(.8 * var(--tca-glow-now))}
.mlx__pulse{display:flex;align-items:center;gap:14px;flex:none;padding-right:24px;
  border-right:1px solid var(--mud-palette-lines-default)}
/* the live status orb: an empty span carrying data-status — all look lives in this CSS */
.mlx__pulse .tca-live-status-orb{width:14px;height:14px;flex:none;border-radius:50%;display:inline-block;
  background:rgba(var(--mud-palette-text-primary-rgb),.25)}
.mlx__pulse .tca-live-status-orb[data-status="started"]{background:var(--mud-palette-success);
  box-shadow:0 0 14px color-mix(in srgb, var(--mud-palette-success) 80%, transparent)}
.mlx__pulse .tca-live-status-orb[data-status="stopped"]{background:var(--mud-palette-error);
  box-shadow:0 0 10px color-mix(in srgb, var(--mud-palette-error) 55%, transparent)}
.mlx__pulse .tca-live-status-orb[data-status="starting"],
.mlx__pulse .tca-live-status-orb[data-status="stopping"]{background:var(--mud-palette-warning);
  box-shadow:0 0 14px color-mix(in srgb, var(--mud-palette-warning) 80%, transparent);
  animation:mlt-glow 1.4s ease-in-out infinite}
.mlx__pulse-stack{display:flex;flex-direction:column;gap:1px}
.mlx__microlabel{font-family:var(--mlt-font-mono);font-size:.58rem;letter-spacing:.16em;
  text-transform:uppercase;opacity:.5}
.mlx__status .tca-live{font-family:var(--mlt-font-display);font-weight:700;font-size:1.3rem;
  letter-spacing:.03em;line-height:1.15}
.mlx__sub{font-family:var(--mlt-font-mono);font-size:.68rem;opacity:.6}
.mlx__sub .tca-live{color:var(--mud-palette-primary)}

/* ---------- the connect jack: the band's one ACTION — a lever, not a readout ---------- */
.mlx__connect{display:flex;align-items:center;gap:12px;flex:none;align-self:center;
  padding:10px 16px 11px;border-radius:12px;text-decoration:none;
  color:var(--mud-palette-text-primary);
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 45%, var(--mud-palette-lines-default));
  background:rgba(var(--mud-palette-surface-rgb),.82);
  box-shadow:0 4px 14px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.05);
  transition:border-color .15s, background .15s}
/* Brighten in place — no hover lift (a translateY on the element's own :hover flees a bottom-edge
   cursor and vibrates). */
.mlx__connect:hover{border-color:var(--mlt-ember-2);
  background:color-mix(in srgb, var(--mlt-ember-2) 12%, rgba(var(--mud-palette-surface-rgb),.85))}
.mlx__connect i{font-size:.95rem;color:var(--tca-ember-now)}
.mlx__connect-stack{display:flex;flex-direction:column;gap:1px;min-width:0}
.mlx__connect-addr{font-family:var(--mlt-font-mono);font-size:.8rem;letter-spacing:.03em;white-space:nowrap}
/* Dead container, dead jack — same live gate as the power buttons, no reload needed either way. */
html[data-tca-status="stopped"] .mlx__connect,
html[data-tca-status="unknown"] .mlx__connect{opacity:.35;filter:grayscale(1);pointer-events:none}
/* Same 2-row grid as the game band: circles row 1, labels row 2, so a wrapped label can't shift a
   circle out of line (flex `align-items:center` did). */
/* `justify-content:center` is docker-only: ports anchor the right edge, so left-packed rings
   left a wide hole in the middle. The game band stays left-packed — network + art fill it. */
.mlx__gauges{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,max-content);
  grid-template-rows:auto auto;justify-items:center;align-content:center;justify-content:center;
  column-gap:26px;row-gap:7px;flex:1;min-width:0}

/* ---------- ring gauges: pure CSS around the live tokens' inline --pct custom property ---------- */
@property --pct { syntax: '<number>'; inherits: false; initial-value: 0; }
/* Flattened into .mlx__gauges' grid (see above). The mobile band restores it to a real box. */
.mlx__ring{display:contents}
.mlx__ring > .tca-live{
  --tca-ring:var(--mud-palette-primary);
  width:74px;height:74px;border-radius:50%;flex:none;
  display:flex;align-items:center;justify-content:center;text-align:center;
  font-family:var(--mlt-font-display);font-weight:700;font-size:.78rem;line-height:1;
  padding:0 9px;overflow:hidden;
  background:
    radial-gradient(closest-side, var(--mud-palette-surface) 77%, transparent 78% 100%),
    conic-gradient(var(--tca-ring) calc(var(--pct) * 1%), color-mix(in srgb, var(--tca-ring) 16%, transparent) 0);
  transition:--pct .9s ease;
  /* Stopped containers still show last-known numbers — drain them so they don't read as live. */
  filter:saturate(calc(1 - var(--tca-cool) * .8));
  opacity:calc(1 - var(--tca-cool) * .5);
}
/* Load ramp off the bridge's bare numbers — see gamehome-live.css. */
.mlx__ring--cpu > .tca-live{
  --tca-heat:clamp(0%, calc((var(--svc-cpu, 0) - 60) * 2.85%), 100%);
  --tca-ring:color-mix(in srgb, var(--mud-palette-error) var(--tca-heat), var(--mlt-ember-2));
}
.mlx__ring--memory > .tca-live{
  --tca-heat:clamp(0%, calc((var(--svc-memory, 0) - 70) * 3.33%), 100%);
  --tca-ring:color-mix(in srgb, var(--mud-palette-error) var(--tca-heat), var(--mud-palette-secondary));
}
.mlx__ring--disk > .tca-live{--tca-ring:var(--mud-palette-tertiary)}
.mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live{font-size:.62rem}
.mlx__ring .mlx__microlabel{max-width:110px;text-align:center;line-height:1.5}
.mlx__ring .mlx__microlabel .tca-live{font-size:inherit;color:inherit}
.mlx__g{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlx__num{font-family:var(--mlt-font-display);font-weight:600;font-size:1.35rem;line-height:1.2;
  white-space:nowrap;display:inline-flex;align-items:baseline}
.mlx__den{font-size:.72rem;opacity:.5;font-weight:500;margin-left:2px}
.mlx__den .tca-live{font-size:inherit}

/* Band member now, not a row of its own — pinned right by .mlx__gauges' flex:1 behind a hairline,
   so the band reads status | telemetry | ports. */
.mlx__ports{min-width:0;display:flex;align-items:center;justify-content:flex-end;flex:none;
  padding-left:26px;border-left:1px solid var(--mud-palette-lines-default)}

/* container deck (visibility-toggled fixed-height panels so both terminals measure) */
.mlx__deck{
  min-width:0;border-radius:var(--mlt-radius);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, rgba(255,255,255,.02), transparent 50%), rgba(var(--mud-palette-surface-rgb),.94);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
}
.mlx__tin{display:none}
.mlx__deckbar{display:flex;align-items:center;gap:14px;padding:10px 14px;
  border-bottom:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(90deg, rgba(var(--mlt-ember-rgb),.06), transparent 55%)}
.mlx__decktag{font-family:var(--mlt-font-mono);font-size:.6rem;letter-spacing:.16em;
  text-transform:uppercase;opacity:.45;flex:none}
.mlx__tabs{display:flex;gap:6px;margin-left:auto}
.mlx__tab{display:inline-flex;align-items:center;gap:8px;height:32px;padding:0 14px;border-radius:9px;
  cursor:pointer;font-family:var(--mlt-font-display);font-size:.74rem;letter-spacing:.07em;
  text-transform:uppercase;opacity:.6;transition:opacity .15s, background .15s, color .15s;
  border:1px solid transparent}
.mlx__tab:hover{opacity:1;background:rgba(var(--mud-palette-primary-rgb),.07)}
.mlx__tab i{font-size:.72rem}
#mlx-dt-logs:checked ~ .mlx__deckbar label[for="mlx-dt-logs"],
#mlx-dt-term:checked ~ .mlx__deckbar label[for="mlx-dt-term"],
#mlx-dt-details:checked ~ .mlx__deckbar label[for="mlx-dt-details"],
#mlx-dt-advanced:checked ~ .mlx__deckbar label[for="mlx-dt-advanced"]{
  opacity:1;color:var(--mud-palette-primary);
  background:rgba(var(--mud-palette-primary-rgb),.1);
  border-color:rgba(var(--mud-palette-primary-rgb),.35)}
.mlx__panels{position:relative;height:460px;min-width:0}
.mlx__panel{position:absolute;inset:0;visibility:hidden;min-width:0;overflow:hidden}
.mlx__p-details,.mlx__p-advanced{overflow-y:auto;padding:16px}
#mlx-dt-logs:checked ~ .mlx__panels .mlx__p-logs{visibility:visible}
#mlx-dt-term:checked ~ .mlx__panels .mlx__p-term{visibility:visible}
#mlx-dt-details:checked ~ .mlx__panels .mlx__p-details{visibility:visible}
#mlx-dt-advanced:checked ~ .mlx__panels .mlx__p-advanced{visibility:visible}
/* Logs + terminal cool with the forge, same values as the game console. Details/Advanced do
   NOT — static facts and actions stay just as relevant on a stopped container. */
.mlx__p-logs,.mlx__p-term{filter:grayscale(var(--tca-cool)) contrast(calc(1 - var(--tca-cool) * .22));
  opacity:calc(1 - var(--tca-cool) * .45)}
.mlx__panel .mud-paper{background:transparent;border:none;box-shadow:none;border-radius:0}
.mlx__panel .docker-terminal-wrapper{background:transparent;border:none;box-shadow:none}

@media (max-width:959.98px){
  .mlx__panels{height:400px}
  /* Same stacked band as the game home — 3 rings here, one aligned row */
  .mlx__band{flex-direction:column;align-items:stretch;gap:12px;padding:14px 14px 16px}
  .mlx__band::after{right:32%}
  .mlx__pulse{padding-right:0;padding-bottom:11px;border-right:none;
    border-bottom:1px solid var(--mud-palette-lines-default)}
  /* Stacked band: ports become the last full-width row, so the vertical divider turns horizontal. */
  .mlx__ports{padding-left:0;padding-top:11px;border-left:none;justify-content:center;
    border-top:1px solid var(--mud-palette-lines-default)}
  /* The jack becomes its own full-width row between the rings and the ports. */
  .mlx__connect{justify-content:center}
  .mlx__gauges{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;align-items:start}
  /* The ring is the grid item here, so it must be a real box again (desktop flattens it). */
  .mlx__ring{display:flex;flex-direction:column;align-items:center;gap:7px;min-width:0;width:100%}
  .mlx__ring > .tca-live{width:58px;height:58px;font-size:.66rem;padding:0 5px}
  .mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live{font-size:.55rem}
  .mlx__ring .mlx__microlabel{max-width:100%;font-size:.5rem;letter-spacing:.09em}
  .mlx__deckbar{flex-wrap:wrap}
  .mlx__decktag{display:none}
  .mlx__tabs{margin-left:0}
  .mlx__tab span{display:none}
  .mlx__tab{padding:0 12px}
  .mlx__tab i{font-size:.85rem}
}
/* Phones: page scrolls, not a 400px box inside it — see the long note in gamehome-live.css.
   Docker has TWO terminals (logs + exec); both keep the fixed 70vh absolute box. */
@media (max-width:599.98px){
  .mlx__panels{height:auto;min-height:220px}
  .mlx__panel{position:relative;inset:auto;display:none;overflow:visible}
  #mlx-dt-details:checked  ~ .mlx__panels .mlx__p-details,
  #mlx-dt-advanced:checked ~ .mlx__panels .mlx__p-advanced{display:block;visibility:visible}
  .mlx__p-logs,.mlx__p-term{position:absolute;top:0;left:0;right:0;height:70vh;display:block;overflow:hidden}
  #mlx-dt-logs:checked ~ .mlx__panels,
  #mlx-dt-term:checked ~ .mlx__panels{height:70vh}
}
@media (max-width:399.98px){
  .mlx__gauges{gap:6px}
  .mlx__ring > .tca-live{width:50px;height:50px;font-size:.58rem;padding:0 3px}
  .mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live{font-size:.48rem}
}
@media (prefers-reduced-motion: reduce){.mlx__orb{animation:none}}

.mud-container:has(> .mlt-svh){margin-top:4px!important;padding-top:0!important}
.mlt-svh{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:0 2px}

/* lockup: icon chip + live name + identity line */
.mlt-svh__lockup{display:flex;align-items:center;gap:14px;flex:1 1 300px;min-width:0}
.mlt-svh__chip{
  width:46px;height:46px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:12px;
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 32%, transparent);
  color:var(--tca-ember-now);
  background:linear-gradient(160deg, color-mix(in srgb, var(--tca-ember-now) 14%, transparent),
                                     color-mix(in srgb, var(--tca-ember-now) 4%, transparent));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.mlt-svh__stack{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlt-svh__name .tca-live-name{
  font-family:var(--mlt-font-display);font-weight:700;font-size:clamp(1.35rem,2.1vw,1.8rem);
  line-height:1.1;letter-spacing:.015em;display:block;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.mlt-svh__ident{font-size:.64rem;opacity:.55;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* connection cards: author chrome around the chrome-less address atoms */
.mlt-svh__conns{gap:10px;align-items:stretch;min-width:0}
.mlt-svh__conncard{
  display:flex;flex-direction:column;gap:3px;justify-content:center;
  padding:7px 12px;border-radius:10px;min-width:0;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-surface-rgb),.55);
}
.mlt-svh__connlabel{font-size:.55rem;opacity:.5}
.tca-conn{font-family:var(--mlt-font-mono);font-size:.74rem;display:inline-flex;align-items:center;
  gap:2px;white-space:nowrap}
.tca-conn .mud-icon-button{padding:2px;margin-left:2px}

/* per-action power buttons (chrome-less <button> atoms styled from scratch) */
.mlt-svh__power{display:flex;align-items:center;gap:10px;margin-left:auto;flex-wrap:wrap}
.tca-power{
  display:inline-flex;align-items:center;gap:9px;height:40px;padding:0 18px;border-radius:11px;
  font-family:var(--mlt-font-display);font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  font-size:.78rem;border:1px solid transparent;cursor:pointer;background:transparent;color:inherit;
  transition:filter .15s, box-shadow .15s, transform .12s, background .15s;
}
.tca-power:active{transform:translateY(1px)}
.tca-power:disabled{opacity:.45;cursor:default}
.tca-power__icon{font-size:.72rem}
.tca-power-start{
  background:var(--mlt-molten);color:var(--mlt-ink-on-ember);
  box-shadow:0 4px 16px rgba(var(--mlt-ember-rgb),.32), inset 0 1px 0 rgba(255,255,255,.38);
}
.tca-power-start:hover:not(:disabled){filter:brightness(1.07);box-shadow:0 6px 22px rgba(var(--mlt-ember-rgb),.5)}
.tca-power-restart{border-color:color-mix(in srgb, var(--mud-palette-warning) 55%, transparent);color:var(--mud-palette-warning)}
.tca-power-restart:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-warning) 12%, transparent)}
.tca-power-stop{border-color:color-mix(in srgb, var(--mud-palette-error) 55%, transparent);color:var(--mud-palette-error)}
.tca-power-stop:hover:not(:disabled){background:color-mix(in srgb, var(--mud-palette-error) 12%, transparent)}
.tca-power-kill{background:var(--mud-palette-error);color:#fff;box-shadow:0 4px 14px color-mix(in srgb, var(--mud-palette-error) 45%, transparent)}
.tca-power-kill:hover:not(:disabled){filter:brightness(1.08)}

/* Seam + chip follow the forge. The header renders on EVERY page, so this is what carries the
   status cue into Console / Files / Scheduled Tasks. */
.mlt-svh__seam{height:2px;border-radius:2px;margin:12px 2px 18px;
  opacity:calc(.85 * var(--tca-glow-now));
  background:linear-gradient(90deg,transparent,var(--tca-ember-now) 18%,
             color-mix(in srgb, var(--tca-ember-now) 45%, #fff) 50%, var(--tca-ember-now) 82%,transparent);
  background-size:220% 100%;animation:mlt-flow 30s linear infinite}

@media (max-width:959.98px){
  /* Power stays on the name's line: drop the lockup's 300px basis so the (ellipsised) name gives
     up width instead of wrapping the buttons to their own row. */
  .mlt-svh{gap:12px;flex-wrap:nowrap}
  .mlt-svh__lockup{flex:1 1 auto;gap:10px}
  .mlt-svh__power{margin-left:auto;width:auto;flex:none;flex-wrap:nowrap;gap:8px}
  .tca-power{height:36px;padding:0 14px;font-size:.72rem}
  .mlt-svh__chip{width:40px;height:40px;border-radius:10px}
  .mlt-svh__seam{margin:10px 2px 12px}
}
/* Phones: icon-only buttons so the name keeps a readable share. Colour still separates them. */
@media (max-width:599.98px){
  .tca-power__label{display:none}
  .tca-power{padding:0 12px;gap:0}
  .tca-power__icon{font-size:.85rem}
}

.mlx{display:flex;flex-direction:column;gap:16px}
.mlx__alert:empty{display:none}

/* ---------- the telemetry band: author-owned markup around headless live-* values ---------- */
.mlx__band{
  display:flex;align-items:stretch;gap:28px;flex-wrap:wrap;
  padding:16px 22px;border-radius:var(--mlt-radius);
  border:1px solid var(--mud-palette-lines-default);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
  position:relative;overflow:hidden;isolation:isolate;
}
/* Art window: fill lives on ::before so it can be masked WITHOUT masking the readouts — that
   lets the layout's hero (.mud-paper.img-bg, z-index -10) show through the band's dead half. */
.mlx__band::before{content:"";position:absolute;inset:0;z-index:-1;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--tca-ember-now) 8%, transparent), transparent 45%),
    linear-gradient(270deg, color-mix(in srgb, var(--tca-ember-now) 16%, transparent), transparent 40%),
    rgba(var(--mud-palette-surface-rgb),.94);
}
/* Only where art EXISTS — .img-bg is absent (not empty) when a blueprint has none, so :has()
     keeps this self-healing. Fade is px-from-left: the content run is fixed, the band isn't.
     Floor 62% / glaze 16% — below that the band stops reading as a panel. */
body:has(.img-bg) .mlx__band::before{
  -webkit-mask-image:linear-gradient(90deg,#000 0 880px,rgba(0,0,0,.85) 1040px,rgba(0,0,0,.62) 1200px);
  mask-image:linear-gradient(90deg,#000 0 880px,rgba(0,0,0,.85) 1040px,rgba(0,0,0,.62) 1200px)}
/* The ember seam under the band is the loudest heat cue — it drains to ash when the forge is out. */
.mlx__band::after{content:"";position:absolute;left:0;right:55%;bottom:0;height:2px;
  background:linear-gradient(90deg,var(--tca-ember-now),color-mix(in srgb, var(--tca-ember-now) 45%, #fff) 45%,transparent);
  opacity:calc(.8 * var(--tca-glow-now))}
.mlx__pulse{display:flex;align-items:center;gap:14px;flex:none;padding-right:24px;
  border-right:1px solid var(--mud-palette-lines-default)}
/* the live status orb: an empty span carrying data-status — all look lives in this CSS */
.mlx__pulse .tca-live-status-orb{width:14px;height:14px;flex:none;border-radius:50%;display:inline-block;
  background:rgba(var(--mud-palette-text-primary-rgb),.25)}
.mlx__pulse .tca-live-status-orb[data-status="started"]{background:var(--mud-palette-success);
  box-shadow:0 0 14px color-mix(in srgb, var(--mud-palette-success) 80%, transparent)}
.mlx__pulse .tca-live-status-orb[data-status="stopped"]{background:var(--mud-palette-error);
  box-shadow:0 0 10px color-mix(in srgb, var(--mud-palette-error) 55%, transparent)}
.mlx__pulse .tca-live-status-orb[data-status="starting"],
.mlx__pulse .tca-live-status-orb[data-status="stopping"]{background:var(--mud-palette-warning);
  box-shadow:0 0 14px color-mix(in srgb, var(--mud-palette-warning) 80%, transparent);
  animation:mlt-glow 1.4s ease-in-out infinite}
.mlx__pulse-stack{display:flex;flex-direction:column;gap:1px}
.mlx__microlabel{font-family:var(--mlt-font-mono);font-size:.58rem;letter-spacing:.16em;
  text-transform:uppercase;opacity:.5}
.mlx__status .tca-live{font-family:var(--mlt-font-display);font-weight:700;font-size:1.3rem;
  letter-spacing:.03em;line-height:1.15}
.mlx__sub{font-family:var(--mlt-font-mono);font-size:.68rem;opacity:.6}
.mlx__sub .tca-live{color:var(--mud-palette-primary)}

/* ---------- the connect jack: the band's one ACTION — a lever, not a readout ---------- */
/* Floats on the art window, so it carries its own glazed surface for legibility. */
.mlx__connect{display:flex;align-items:center;gap:12px;flex:none;align-self:center;
  padding:10px 16px 11px;border-radius:12px;text-decoration:none;
  color:var(--mud-palette-text-primary);
  border:1px solid color-mix(in srgb, var(--tca-ember-now) 45%, var(--mud-palette-lines-default));
  background:rgba(var(--mud-palette-surface-rgb),.82);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
  box-shadow:0 4px 14px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.05);
  transition:border-color .15s, background .15s}
/* Brighten in place — no hover lift (a translateY on the element's own :hover flees a bottom-edge
   cursor and vibrates). */
.mlx__connect:hover{border-color:var(--mlt-ember-2);
  background:color-mix(in srgb, var(--mlt-ember-2) 12%, rgba(var(--mud-palette-surface-rgb),.85))}
.mlx__connect i{font-size:.95rem;color:var(--tca-ember-now)}
.mlx__connect-stack{display:flex;flex-direction:column;gap:1px;min-width:0}
.mlx__connect-addr{font-family:var(--mlt-font-mono);font-size:.8rem;letter-spacing:.03em;white-space:nowrap}
/* Dead server, dead jack — same live gate as the power buttons, no reload needed either way. */
html[data-tca-status="stopped"] .mlx__connect,
html[data-tca-status="unknown"] .mlx__connect{opacity:.35;filter:grayscale(1);pointer-events:none}

/* 2-row grid — circles row 1, labels row 2 — so a wrapping label can't shift a circle out of
   line, which flex align-items:center did. `display:contents` flattens the ring into it. */
.mlx__gauges{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,max-content);
  grid-template-rows:auto auto;justify-items:center;align-content:center;
  column-gap:26px;row-gap:7px;flex:1;min-width:0}

/* ---------- ring gauges: pure CSS around the live tokens' inline --pct custom property ---------- */
/* --pct is engine-published per live span; everything defined here is --tca-* (the only
   namespace a SANDBOXED template may define), so the gauge technique ports unchanged. MOLTEN
   itself still needs full trust for @property / @media / @keyframes and the --mlt-* tokens. */
@property --pct { syntax: '<number>'; inherits: false; initial-value: 0; }
@property --tca-pct { syntax: '<number>'; inherits: false; initial-value: 0; }
/* Flattened into .mlx__gauges' grid (see above). The mobile band restores it to a real box. */
.mlx__ring{display:contents}
.mlx__ring > .tca-live,
.mlx__ring > .mlx__dial{
  --tca-ring:var(--mud-palette-primary);
  width:74px;height:74px;border-radius:50%;flex:none;
  display:flex;align-items:center;justify-content:center;text-align:center;
  font-family:var(--mlt-font-display);font-weight:700;font-size:.78rem;line-height:1;
  padding:0 9px;overflow:hidden;
  background:
    radial-gradient(closest-side, var(--mud-palette-surface) 77%, transparent 78% 100%),
    conic-gradient(var(--tca-ring) calc(var(--tca-sweep) * 1%), color-mix(in srgb, var(--tca-ring) 16%, transparent) 0);
  /* A stopped service still shows LAST-KNOWN numbers; at full colour they read as live. Drain them. */
  filter:saturate(calc(1 - var(--tca-cool) * .8));
  opacity:calc(1 - var(--tca-cool) * .5);
}
/* One gradient, two sources, via the unregistered alias --tca-sweep. A var(--pct,var(--tca-pct,0))
   chain would NOT work here: @property gives --pct an initial value, so the fallback never fires.
   (Sandboxed templates have no @property — there the chain IS the right shape.) */
.mlx__ring > .tca-live{--tca-sweep:var(--pct);transition:--pct .9s ease}
.mlx__ring > .mlx__dial{--tca-sweep:var(--tca-pct);transition:--tca-pct .9s ease}
.mlx__ring--players > .tca-live,
.mlx__ring--players > .mlx__dial{--tca-ring:var(--mud-palette-success)}
/* A dial holds TWO live tokens ("25/32"), so it can't read a child's --pct — custom properties
   only inherit DOWN. It takes the page-scoped --svc-* the bridge publishes on <html>. */
.mlx__ring--players > .mlx__dial{--tca-pct:var(--svc-players, 0)}
.mlx__ring--memory > .mlx__dial{--tca-pct:var(--svc-memory, 0)}
.mlx__dial .tca-live{font-size:inherit;color:inherit}
.mlx__dial-max{font-size:.74em;opacity:.5;font-weight:600}
/* Two long humanized byte values won't sit side by side in a 74px circle — stack them. */
.mlx__dial--stack{flex-direction:column;gap:1px;line-height:1.15}
/* Load ramp: --svc-* are BARE NUMBERS, so CSS arithmetic can shade toward danger with no JS.
   CPU ramps 60→95%, memory 70→100%. */
.mlx__ring--cpu > .tca-live{
  --tca-heat:clamp(0%, calc((var(--svc-cpu, 0) - 60) * 2.85%), 100%);
  --tca-ring:color-mix(in srgb, var(--mud-palette-error) var(--tca-heat), var(--mlt-ember-2));
}
.mlx__ring--memory > .tca-live,
.mlx__ring--memory > .mlx__dial{
  --tca-heat:clamp(0%, calc((var(--svc-memory, 0) - 70) * 3.33%), 100%);
  --tca-ring:color-mix(in srgb, var(--mud-palette-error) var(--tca-heat), var(--mud-palette-secondary));
}
.mlx__ring--disk > .tca-live,
.mlx__ring--disk > .mlx__dial{--tca-ring:var(--mud-palette-tertiary)}
.mlx__ring--disk > .mlx__dial{--tca-pct:var(--svc-disk, 0)}
.mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live,
.mlx__ring--memory > .mlx__dial,.mlx__ring--disk > .mlx__dial{font-size:.62rem}
.mlx__ring .mlx__microlabel{max-width:110px;text-align:center;line-height:1.5}
.mlx__ring .mlx__microlabel .tca-live{font-size:inherit;color:inherit}
.mlx__g{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlx__num{font-family:var(--mlt-font-display);font-weight:600;font-size:1.35rem;line-height:1.2;
  white-space:nowrap;display:inline-flex;align-items:baseline}
.mlx__den{font-size:.72rem;opacity:.5;font-weight:500;margin-left:2px}
.mlx__den .tca-live{font-size:inherit}
.mlx__num--net{font-size:.95rem;gap:6px;display:inline-flex;align-items:center}
.mlx__num--net i{font-size:.62rem;color:var(--mud-palette-primary);opacity:.8;margin:0 2px}

/* ---------- Furnace deck: radio-tab switcher over a fixed-height stage ---------- */
.mlx__main{display:grid;grid-template-columns:minmax(0,1fr);gap:16px;align-items:start}
.mlx__main--side{grid-template-columns:minmax(0,1fr) minmax(0,352px)}
.mlx__deck{
  min-width:0;border-radius:var(--mlt-radius);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, rgba(255,255,255,.02), transparent 50%), rgba(var(--mud-palette-surface-rgb),.94);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
}
.mlx__tin{display:none}
.mlx__deckbar{display:flex;align-items:center;gap:14px;padding:10px 14px;
  border-bottom:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(90deg, rgba(var(--mlt-ember-rgb),.06), transparent 55%)}
.mlx__decktag{font-family:var(--mlt-font-mono);font-size:.6rem;letter-spacing:.16em;
  text-transform:uppercase;opacity:.45;flex:none}
.mlx__tabs{display:flex;gap:6px;margin-left:auto}
.mlx__tab{display:inline-flex;align-items:center;gap:8px;height:32px;padding:0 14px;border-radius:9px;
  cursor:pointer;font-family:var(--mlt-font-display);font-size:.74rem;letter-spacing:.07em;
  text-transform:uppercase;opacity:.6;transition:opacity .15s, background .15s, color .15s;
  border:1px solid transparent}
.mlx__tab:hover{opacity:1;background:rgba(var(--mud-palette-primary-rgb),.07)}
.mlx__tab i{font-size:.72rem}
#mlx-gt-console:checked ~ .mlx__deckbar label[for="mlx-gt-console"],
#mlx-gt-details:checked ~ .mlx__deckbar label[for="mlx-gt-details"],
#mlx-gt-advanced:checked ~ .mlx__deckbar label[for="mlx-gt-advanced"]{
  opacity:1;color:var(--mud-palette-primary);
  background:rgba(var(--mud-palette-primary-rgb),.1);
  border-color:rgba(var(--mud-palette-primary-rgb),.35)}
.mlx__panels{position:relative;height:540px;min-width:0}
.mlx__panel{position:absolute;inset:0;visibility:hidden;min-width:0;overflow:hidden}
.mlx__p-details,.mlx__p-advanced{overflow-y:auto;padding:16px}
#mlx-gt-console:checked ~ .mlx__panels .mlx__p-console{visibility:visible}
#mlx-gt-details:checked ~ .mlx__panels .mlx__p-details{visibility:visible}
#mlx-gt-advanced:checked ~ .mlx__panels .mlx__p-advanced{visibility:visible}
/* The console cools too — a stopped service's last output is a record, not a live feed.
   grayscale plus a real opacity drop, not a gentle desaturate: one strong cue reads as intent,
   several weak ones read as a bug. Legibility is the floor — people read a dead console to find
   out why it died. Animates for free off the registered --tca-cool. */
.mlx__p-console{filter:grayscale(var(--tca-cool)) contrast(calc(1 - var(--tca-cool) * .22));
  opacity:calc(1 - var(--tca-cool) * .45)}
.mlx__p-console .mud-paper{background:transparent;border:none;box-shadow:none;border-radius:0}
.mlx__p-details .mud-paper,.mlx__p-advanced .mud-paper{border:none;box-shadow:none;background:transparent}

.mlx__side{display:flex;flex-direction:column;gap:16px;min-width:0}
.mlx__sidecard{min-width:0}
/* custom telemetry cards around the chrome-less list atoms */
.mlx__sidecard--custom{
  border-radius:var(--mlt-radius);overflow:hidden;
  border:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, rgba(255,255,255,.02), transparent 50%), rgba(var(--mud-palette-surface-rgb),.94);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
}
.mlx__sidehead{display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:9px 14px;border-bottom:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(90deg, rgba(var(--mlt-ember-rgb),.06), transparent 55%)}
.mlx__sidelink{font-size:.58rem;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;
  color:var(--mud-palette-primary);opacity:.85;transition:opacity .15s}
.mlx__sidelink:hover{opacity:1}
.tca-list{display:block;max-height:246px;overflow-y:auto}

@media (max-width:1279.98px){
  .mlx__main--side{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:959.98px){
  .mlx__side{display:none}
  .mlx__panels{height:440px}
  /* One grid for the whole band: status + network in row 1, rings aligned in row 2.
     `display:contents` flattens the gauge children in. Flex-wrap gave a ragged 2x2 + a
     third row. */
  .mlx__band{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 10px;
    align-items:start;padding:14px 14px 16px}
  .mlx__band::after{right:32%}
  /* Stacked band uses the full width — no dead zone, no window. Repeat the `body:has(.img-bg)`
     prefix or this loses on specificity (0,1,1 vs 0,2,2) and the window opens on phones anyway. */
  body:has(.img-bg) .mlx__band::before{-webkit-mask-image:none;mask-image:none}
  .mlx__pulse{grid-column:1/3;grid-row:1;align-self:stretch;padding-right:0;padding-bottom:11px;
    border-right:none;border-bottom:1px solid var(--mud-palette-lines-default)}
  .mlx__band:not(:has(.mlx__g--net)) .mlx__pulse{grid-column:1/-1}
  .mlx__gauges{display:contents}
  /* Here the RING is the grid item, so it must be a real box again (desktop flattens it). */
  .mlx__ring{display:flex;flex-direction:column;align-items:center;gap:7px;min-width:0;
    grid-row:2;width:100%}
  .mlx__ring > .tca-live,
  .mlx__ring > .mlx__dial{width:58px;height:58px;font-size:.66rem;padding:0 5px}
  .mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live,
  .mlx__ring--memory > .mlx__dial,.mlx__ring--disk > .mlx__dial{font-size:.55rem}
  .mlx__ring .mlx__microlabel{max-width:100%;font-size:.5rem;letter-spacing:.09em}
  /* rides in the status row, right-aligned, sharing its divider */
  .mlx__g--net{grid-column:3/-1;grid-row:1;align-self:stretch;align-items:flex-end;
    justify-content:center;gap:3px;padding-bottom:11px;
    border-bottom:1px solid var(--mud-palette-lines-default)}
  .mlx__num--net{font-size:.9rem}
  /* The jack gets its own full-width row under the rings — unplaced it would auto-flow into the
     ring row's grid cells. */
  .mlx__connect{grid-column:1/-1;grid-row:3;justify-content:center}
  .mlx__deckbar{flex-wrap:wrap}
  .mlx__decktag{display:none}
  .mlx__tabs{margin-left:0}
  .mlx__tab span{display:none}
  .mlx__tab{padding:0 12px}
  .mlx__tab i{font-size:.85rem}
}
/* Phones: the page scrolls, not a 440px box inside it (a nested scroller is a trap — you flick
   the card and the page moves). Non-terminal panels rejoin the flow so the stage grows to fit.
   The console can't: xterm renders 0 rows in a zero-height box, so it keeps an absolute box at a
   fixed 70vh — not inset:0, or another tab resizes it under a live terminal and leaves it at the
   wrong column count. The stage matches 70vh only while the console is selected. */
@media (max-width:599.98px){
  .mlx__panels{height:auto;min-height:220px}
  .mlx__panel{position:relative;inset:auto;display:none;overflow:visible}
  #mlx-gt-details:checked  ~ .mlx__panels .mlx__p-details,
  #mlx-gt-advanced:checked ~ .mlx__panels .mlx__p-advanced{display:block;visibility:visible}
  .mlx__p-console{position:absolute;top:0;left:0;right:0;height:70vh;display:block;overflow:hidden}
  #mlx-gt-console:checked ~ .mlx__panels{height:70vh}
}
@media (max-width:399.98px){
  .mlx__gauges{gap:6px}
  .mlx__ring > .tca-live,
  .mlx__ring > .mlx__dial{width:50px;height:50px;font-size:.58rem;padding:0 3px}
  .mlx__ring--memory > .tca-live,.mlx__ring--disk > .tca-live,
  .mlx__ring--memory > .mlx__dial,.mlx__ring--disk > .mlx__dial{font-size:.48rem}
}
@media (prefers-reduced-motion: reduce){.mlx__orb{animation:none}}

/* ============ MOLTEN · LoginPage surface — split forge ============ */
.auth-bg-image{display:none!important}
.auth-footer{display:none!important}

.mlt-login{position:fixed;inset:0;display:flex;z-index:0;font-family:var(--mlt-font-body)}

/* ---------- left: the furnace (always dark, poster-grade) ---------- */
.mlt-login__brand{
  flex:1 1 54%;min-width:0;position:relative;overflow:hidden;color:var(--mlt-ink-bright);
  background:
    radial-gradient(1100px 640px at 8% 112%, rgba(var(--mlt-ember-hot-rgb),.34), transparent 62%),
    radial-gradient(700px 420px at 82% -10%, rgba(var(--mlt-counter-rgb),.10), transparent 55%),
    var(--mlt-backdrop);
}
.mlt-login__brand::before{ /* iron grain */
  content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;
  background:
    repeating-linear-gradient(115deg, rgba(255,255,255,.016) 0 1px, transparent 1px 7px),
    repeating-linear-gradient(295deg, rgba(0,0,0,.03) 0 1px, transparent 1px 9px);
}
.mlt-login__brand::after{ /* molten pool on the floor */
  content:"";position:absolute;left:-10%;right:30%;bottom:-2px;height:3px;
  background:var(--mlt-seam-h);background-size:220% 100%;
  animation:mlt-flow 22s linear infinite;filter:blur(.4px);
  box-shadow:0 0 24px rgba(var(--mlt-ember-rgb),.75);
}
.mlt-login__brand-inner{
  position:relative;z-index:1;height:100%;display:flex;flex-direction:column;
  justify-content:center;gap:26px;padding:56px 8vw 64px;max-width:640px;
  animation:mlt-rise .5s ease-out both;
}
.mlt-login__lockup{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.mlt-login__word{font-family:var(--mlt-font-brand);font-weight:var(--mlt-brand-weight);font-size:1.6rem;letter-spacing:.14em}
.mlt-login__word-tag{font-size:.62rem;opacity:.55;border:1px solid rgba(255,255,255,.18);
  border-radius:6px;padding:4px 8px}
/* Poster moments (headline + sign-in h2) ride --mlt-font-brand, so a sibling theme changes its
   display voice without owning this row. Weight stays 700 here — a sibling on a single-weight
   face corrects that in its own sheet. */
.mlt-login__headline{
  font-family:var(--mlt-font-brand);font-weight:700;line-height:.98;
  font-size:clamp(3rem,6vw,5.2rem);margin:0;letter-spacing:.01em;
}
.mlt-login__seam{width:180px}
.mlt-login__lede{font-size:1.05rem;line-height:1.6;opacity:.72;margin:0;max-width:44ch}
.mlt-login__feats{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-direction:column;gap:18px}
.mlt-login__feats li{display:flex;gap:16px;align-items:flex-start}
.mlt-login__feats i{
  width:38px;height:38px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:10px;font-size:15px;color:var(--mlt-ember-1);
  background:rgba(var(--mlt-ember-rgb),.10);border:1px solid rgba(var(--mlt-ember-rgb),.28);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.mlt-login__feats strong{display:block;font-weight:600;font-size:.95rem;letter-spacing:.01em}
.mlt-login__feats span{display:block;font-size:.83rem;opacity:.55;margin-top:2px}
.mlt-login__foot{font-size:.62rem;opacity:.4;margin-top:6px}

/* ---------- right: the sign-in panel (machined plate, follows theme mode) ---------- */
.mlt-login__panel{
  flex:1 1 46%;min-width:0;display:flex;align-items:center;justify-content:center;
  background:var(--mud-palette-background);position:relative;overflow-y:auto;
}
.mlt-login__panel::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(640px 420px at 84% 108%, rgba(var(--mlt-ember-rgb),.07), transparent 60%);
}
.mlt-login__card{
  position:relative;width:min(420px, 92%);padding:38px 6px;
  animation:mlt-rise .5s ease-out .08s both;
}
.mlt-login__panel-head{margin-bottom:20px}
.mlt-login__panel-tag{font-size:.62rem;color:var(--mud-palette-primary);opacity:.9}
.mlt-login__panel-head h2{
  font-family:var(--mlt-font-brand);font-weight:700;font-size:2rem;margin:6px 0 0;
  color:var(--mud-palette-text-primary);
}
.mlt-login__meta{display:flex;justify-content:center;margin-top:18px;opacity:.8}

/* tame browser autofill tint so it doesn't torch the field */
.mlt-login input:-webkit-autofill,.mlt-login input:-webkit-autofill:hover,.mlt-login input:-webkit-autofill:focus{
  -webkit-box-shadow:0 0 0 1000px var(--mud-palette-surface) inset;
  -webkit-text-fill-color:var(--mud-palette-text-primary);
  caret-color:var(--mud-palette-text-primary);
}

/* de-card the stock login form: the panel IS the surface */
.mlt-login .mud-paper:not(.mud-popover){background:transparent;box-shadow:none;border:none;padding:0}
.mlt-login .mud-card-content{padding:0}
.mlt-login .mud-button-filled-primary{width:100%;height:46px;font-size:.95rem}

/* ---------- phone tier: furnace becomes the masthead ---------- */
@media (max-width:959.98px){
  .mlt-login{flex-direction:column;overflow-y:auto}
  .mlt-login__brand{flex:none;min-height:230px}
  .mlt-login__brand-inner{padding:30px 26px 34px;gap:14px;justify-content:flex-end;max-width:none}
  .mlt-login__headline{font-size:2.2rem}
  .mlt-login__feats,.mlt-login__foot,.mlt-login__lede{display:none}
  .mlt-login__panel{flex:1 0 auto;align-items:flex-start}
  .mlt-login__card{padding:26px 6px 40px}
}

contents.content:
{% comment %} MOLTEN keeps the composed Mud chrome — drawer coordination, mobile overlay,
impersonation banner, announcements all stay functional — and re-forges it purely in CSS.
{% endcomment %}
{% component "shell" %}

contents.css:
/* ============ MOLTEN · Shell surface (authenticated chrome) ============
   Floating island chrome — inset rounded drawer, appbar and footer over a cold-iron forge
   floor. Composed {% component "shell" %}, so MudBlazor keeps layout coordination. */

/* ---------- background canvas (ember atmosphere) ---------- */
.mud-layout{background:transparent!important}
body{background:var(--mud-palette-background)}
.mud-layout::before{
  content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:
    radial-gradient(1000px 560px at 10% 110%, rgba(var(--mlt-ember-rgb),.14), transparent 62%),
    radial-gradient(760px 440px at 92% -8%, rgba(var(--mlt-counter-rgb),.07), transparent 55%),
    linear-gradient(180deg, transparent, rgba(0,0,0,.12));
}
.mud-layout.dark-mode::after{
  content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.55;
  background:
    repeating-linear-gradient(115deg, rgba(255,255,255,.013) 0 1px, transparent 1px 7px),
    repeating-linear-gradient(295deg, rgba(0,0,0,.02) 0 1px, transparent 1px 9px);
}

/* ---------- floating command bar (appbar) ---------- */
.mud-appbar.mud-appbar-fixed-top{
  top:12px;left:24px;right:12px;width:auto!important;
  border-radius:16px;
  background:linear-gradient(180deg, rgba(255,255,255,.03), transparent 60%), rgba(var(--mud-palette-surface-rgb),.86);
  -webkit-backdrop-filter:blur(16px) saturate(1.25);backdrop-filter:blur(16px) saturate(1.25);
  border:1px solid color-mix(in srgb, var(--mud-palette-text-primary) 13%, transparent);
  box-shadow:0 10px 30px rgba(0,0,0,.24), inset 0 1px 0 rgba(255,255,255,.05);
  color:var(--mud-palette-appbar-text);
}
.mud-appbar .mud-toolbar{min-height:60px;padding:0 12px 0 8px}
.mud-appbar .mud-icon-button{color:inherit}

/* breadcrumbs as a machined console path (inner .mud-typography would win over the container) */
.mud-appbar .mud-breadcrumbs,
.mud-appbar .mud-breadcrumbs .mud-typography{font-family:var(--mlt-font-mono);font-size:.78rem;letter-spacing:.06em;
  text-transform:uppercase}
.mud-appbar .mud-breadcrumbs{padding:0}
.mud-appbar .mud-breadcrumbs .mud-breadcrumb-separator{color:rgba(var(--mud-palette-primary-rgb),.8);margin:0 2px}
.mud-appbar .mud-breadcrumbs a{opacity:.62;transition:opacity .15s,color .15s;border-radius:6px;padding:2px 4px}
.mud-appbar .mud-breadcrumbs a:hover{opacity:1;color:var(--mud-palette-primary)}
.mud-appbar .mud-breadcrumbs li:last-child a,
.mud-appbar .mud-breadcrumbs li:last-child .mud-breadcrumb-item{opacity:1;color:var(--mud-palette-primary)}

/* ---------- floating island drawer ---------- */
@media (min-width:960px){
  .mud-drawer.mud-drawer-fixed.mud-drawer-pos-left{
    top:12px;left:12px;bottom:12px;height:auto;
    border-radius:18px;
    border:1px solid color-mix(in srgb, var(--mud-palette-text-primary) 13%, transparent);
    background:linear-gradient(180deg, rgba(255,255,255,.028), transparent 140px), rgba(var(--mud-palette-surface-rgb),.74);
    -webkit-backdrop-filter:blur(18px) saturate(1.2);backdrop-filter:blur(18px) saturate(1.2);
    box-shadow:0 14px 40px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,255,255,.05);
    overflow:hidden;
  }
}
.mud-drawer{color:var(--mud-palette-drawer-text)}
.mud-drawer .mud-drawer-content{overflow-x:hidden;background:transparent}
/* slim, quiet drawer scrollbar (scrollbar-width/color beats the webkit pseudos reliably) */
.mud-drawer .mud-drawer-content{scrollbar-width:thin;scrollbar-color:rgba(var(--mud-palette-text-primary-rgb),.16) transparent}

/* nav links: quiet pills, molten seam on the active one */
.mud-layout:has(.mud-appbar) .mud-nav-link{
  margin:2px 10px;border-radius:10px;position:relative;
  font-family:var(--mlt-font-body);font-weight:500;
  transition:background .15s,color .15s;
}
.mud-layout:has(.mud-appbar) .mud-nav-link:hover{background:rgba(var(--mud-palette-primary-rgb),.08)}
.mud-layout:has(.mud-appbar) .mud-nav-link.active{
  background:linear-gradient(90deg, rgba(var(--mlt-ember-rgb),.17), rgba(var(--mlt-ember-rgb),.05) 65%, transparent);
  color:var(--mud-palette-primary);
}
.mud-layout:has(.mud-appbar) .mud-nav-link.active .mud-nav-link-text{font-weight:600}
.mud-layout:has(.mud-appbar) .mud-nav-link.active::before{
  content:"";position:absolute;left:0;top:7px;bottom:7px;width:3px;border-radius:3px;
  background:var(--mlt-seam-v);
  box-shadow:0 0 10px rgba(var(--mlt-ember-rgb),.65);
}
.mud-layout:has(.mud-appbar) .mud-nav-link .mud-nav-link-icon{transition:color .15s}
.mud-layout:has(.mud-appbar) .mud-nav-link.active .mud-nav-link-icon{color:var(--mud-palette-primary)}
/* group headers: small industrial caps */
.mud-nav-group > .mud-nav-link .mud-nav-link-text{
  font-family:var(--mlt-font-display);font-size:.82rem;letter-spacing:.09em;text-transform:uppercase;opacity:.85}
/* collapsed mini rail: drop the inset so Mud re-centers icons (needs (0,4,0) specificity) */
.mud-layout:has(.mud-appbar) .mud-drawer--closed .mud-nav-link{margin-left:0;margin-right:0;border-radius:0;background:transparent}
.mud-layout:has(.mud-appbar) .mud-drawer--closed .mud-nav-link.active::before{top:10px;bottom:10px}

/* ---------- main content clearance for the floating chrome ---------- */
.mud-main-content{
  padding-top:calc(var(--mud-appbar-height,64px) + 34px)!important;
  padding-left:18px;padding-right:6px;
  padding-bottom:74px;
}

/* ---------- floating footer dock ---------- */
footer.mud-appbar.mud-appbar-fixed-bottom{
  bottom:12px;left:24px;right:12px;width:auto!important;height:42px!important;
  border-radius:13px;
  background:rgba(var(--mud-palette-surface-rgb),.86);
  -webkit-backdrop-filter:blur(16px) saturate(1.25);backdrop-filter:blur(16px) saturate(1.25);
  border:1px solid color-mix(in srgb, var(--mud-palette-text-primary) 13%, transparent);
  box-shadow:0 10px 30px rgba(0,0,0,.24), inset 0 1px 0 rgba(255,255,255,.05);
  overflow:hidden;
}
/* Toolbar must exactly fill the dock: Mud's dense-appbar 32px beat our un-!important 42px, so a
   42px toolbar overflowed a 32px pill and the content rode 6px below centre. */
footer.mud-appbar .mud-toolbar{height:100%;min-height:0;padding:0 14px}

/* ---------- steel plating for content cards ---------- */
.mud-main-content .mud-paper:not(.mud-theme-transparent){
  background:linear-gradient(180deg, rgba(255,255,255,.025), transparent 46%), rgba(var(--mud-palette-surface-rgb),.94);
  border:1px solid var(--mud-palette-lines-default);
  border-radius:var(--mlt-radius);
  box-shadow:0 6px 20px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.04);
}
.mud-main-content .mud-table,.mud-main-content .mud-table-container{background:transparent}
/* game/blueprint wallpaper backdrop: fold it into the forge as a masked hero (fades out ~440px down) */
.mud-main-content .mud-paper.img-bg{
  opacity:.42;
  -webkit-mask-image:linear-gradient(180deg, rgba(0,0,0,.9), rgba(0,0,0,.35) 260px, transparent 440px);
  mask-image:linear-gradient(180deg, rgba(0,0,0,.9), rgba(0,0,0,.35) 260px, transparent 440px);
  filter:saturate(.8) contrast(1.02);
}

/* ---------- shared component re-forging ---------- */
/* primary buttons: poured metal */
.mud-button-filled-primary{
  background:var(--mlt-molten);color:var(--mlt-ink-on-ember);
  font-family:var(--mlt-font-display);font-weight:700;letter-spacing:.05em;
  border-radius:10px;
  box-shadow:0 4px 16px rgba(var(--mlt-ember-rgb),.32), inset 0 1px 0 rgba(255,255,255,.38);
  transition:filter .15s, box-shadow .15s, transform .12s;
}
.mud-button-filled-primary:hover{filter:brightness(1.07);box-shadow:0 6px 22px rgba(var(--mlt-ember-rgb),.5)}
.mud-button-filled-primary:active{transform:translateY(1px)}
.mud-button-outlined-primary{border-color:rgba(var(--mud-palette-primary-rgb),.5)}
.mud-button-outlined-primary:hover{background:rgba(var(--mud-palette-primary-rgb),.08);border-color:var(--mud-palette-primary)}
.mud-button-root{text-transform:none}

/* inputs: ember focus ring */
.mud-input.mud-input-outlined .mud-input-outlined-border{transition:border-color .15s, box-shadow .15s}
.mud-input.mud-input-outlined:focus-within .mud-input-outlined-border{
  border-color:var(--mud-palette-primary);
  box-shadow:0 0 0 3px rgba(var(--mlt-ember-rgb),.16);
}

/* tabs: forge toggles */
.mud-tabs-tabbar{background:transparent}
.mud-tab{font-family:var(--mlt-font-display);letter-spacing:.06em;text-transform:uppercase;font-size:.78rem}
.mud-tab.mud-tab-active{color:var(--mud-palette-primary)}
.mud-tab-slider{background:var(--mlt-molten);height:3px;border-radius:3px;box-shadow:0 0 10px rgba(var(--mlt-ember-rgb),.6)}

/* tables + data grids */
.mud-table-head .mud-table-cell,th.mud-table-cell{
  font-family:var(--mlt-font-display);text-transform:uppercase;letter-spacing:.07em;font-size:.7rem;
  color:rgba(var(--mud-palette-text-primary-rgb),.62);
  border-bottom:1px solid var(--mud-palette-lines-default);
}
.mud-table-row:hover .mud-table-cell{background:rgba(var(--mud-palette-primary-rgb),.045)}

/* dialogs + menus: solid machined plates (never glass - readability) */
.mud-dialog{background:var(--mud-palette-surface);border:1px solid var(--mud-palette-lines-default);
  border-radius:16px;box-shadow:0 30px 80px rgba(0,0,0,.5)}
.mud-dialog .mud-dialog-title{font-family:var(--mlt-font-display)}
.mud-overlay-scrim{background:rgba(5,7,10,.62)}
.mud-popover{background:var(--mud-palette-surface);border:1px solid var(--mud-palette-lines-default);
  border-radius:12px;box-shadow:0 18px 48px rgba(0,0,0,.42)}
.mud-list-item:hover{background:rgba(var(--mud-palette-primary-rgb),.07)}

/* chips + badges */
.mud-chip{border-radius:8px;font-weight:500}

/* progress: molten pour */
.mud-progress-linear.mud-primary .mud-progress-linear-bar{background:var(--mlt-molten)}

/* alerts keep their semantics; square them onto the plate look */
.mud-alert{border-radius:12px;border:1px solid var(--mud-palette-lines-default)}

/* ---------- phone tier: keep the stock overlay drawer, tighten the floating chrome ---------- */
@media (max-width:959.98px){
  .mud-appbar.mud-appbar-fixed-top{top:8px;left:8px;right:8px;border-radius:13px}
  footer.mud-appbar.mud-appbar-fixed-bottom{bottom:8px;left:8px;right:8px}
  .mud-main-content{padding-left:8px;padding-right:8px;padding-bottom:66px}
  .mud-drawer.mud-drawer-fixed.mud-drawer-pos-left{border-radius:0 18px 18px 0}
}

.mlt-bc{display:flex;align-items:center;gap:12px;margin:2px 2px 4px}
/* Content sits closer to the seam than to its own children; service homes keep their 14px. */
.mlt-bc:has(+ .mud-container > .mlt-svh){margin-bottom:14px}
.mlt-bc__tag{font-size:.6rem;opacity:.42;flex:none}
.mlt-bc__seam{flex:1;height:1px;background:linear-gradient(90deg, rgba(var(--mlt-ember-rgb),.55), rgba(var(--mlt-ember-rgb),.12) 40%, transparent)}

/* replaces the stock pinned Profile/Logout block */
.mud-drawer .mud-navmenu.mt-auto{display:none}
.mlt-df{
  margin-top:auto;display:flex;align-items:center;gap:6px;
  padding:10px;border-top:1px solid var(--mud-palette-lines-default);
  background:linear-gradient(180deg, transparent, rgba(var(--mlt-ember-rgb),.045));
}
.mlt-df__card{
  display:flex;align-items:center;gap:10px;flex:1;min-width:0;padding:6px 8px;border-radius:10px;
  text-decoration:none;color:inherit;transition:background .15s;
}
.mlt-df__card:hover{background:rgba(var(--mud-palette-primary-rgb),.09)}
.mlt-df__avatar{
  position:relative;width:34px;height:34px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:10px;font-family:var(--mlt-font-display);font-weight:700;font-size:.95rem;color:var(--mlt-ink-on-ember);
  background:linear-gradient(135deg,#e9edf2,#b9c2cc);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.6), 0 2px 6px rgba(0,0,0,.3);
}
.mlt-df__dot{
  position:absolute;right:-3px;bottom:-3px;width:11px;height:11px;border-radius:50%;
  background:var(--mud-palette-success);border:2px solid rgba(20,24,31,.9);
}
.mlt-df__stack{display:flex;flex-direction:column;gap:2px;min-width:0}
.mlt-df__name{font-weight:600;font-size:.86rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mlt-df__role{font-size:.56rem;opacity:.5}
.mlt-df__out{
  width:34px;height:34px;flex:none;display:flex;align-items:center;justify-content:center;
  border-radius:10px;color:inherit;opacity:.6;transition:opacity .15s, background .15s, color .15s;
}
.mlt-df__out:hover{opacity:1;background:rgba(var(--mud-palette-error-rgb),.12);color:var(--mud-palette-error)}
/* mini rail: avatar only */
.mud-drawer--closed .mlt-df{flex-direction:column;padding:8px 4px}
.mud-drawer--closed .mlt-df__card{flex:none;padding:4px;justify-content:center}
.mud-drawer--closed .mlt-df__stack{display:none}

.mlt-ft{display:flex;align-items:center;gap:14px;width:100%;min-width:0}
.mlt-ft__brand-wrap{display:flex;align-items:center;gap:9px;flex:none;
  color:inherit;text-decoration:none;transition:opacity .15s}
.mlt-ft__brand-wrap:hover{opacity:.82}
.mlt-ft__ingot{width:22px;height:22px;border-radius:6px;font-size:11px}
.mlt-ft__brand{font-size:.64rem;letter-spacing:.18em;opacity:.75;flex:none}
.mlt-ft__sep{color:var(--mud-palette-primary);margin:0 4px;opacity:1}
.mlt-ft__links{display:flex;gap:14px;flex:none}
.mlt-ft__links a{color:inherit;text-decoration:none;font-size:.72rem;letter-spacing:.04em;opacity:.6;transition:opacity .15s,color .15s}
.mlt-ft__links a:hover{opacity:1;color:var(--mud-palette-primary)}
.mlt-ft__res{flex:1;min-width:0;display:flex;justify-content:center;overflow:hidden}
/* Page-injected stat chips shrink by default and wrapped "6.47 GB" inside a 42px bar. Pin them. */
.mlt-ft__res .mud-typography{white-space:nowrap;flex:none}
.mlt-ft__res>*{min-width:0}
.mlt-ft__right{display:flex;align-items:center;gap:10px;flex:none}
.mlt-ft__fine{font-size:.58rem;opacity:.4}
.mlt-ft__ver{font-size:.6rem;opacity:.5}
@media (max-width:959.98px){.mlt-ft__fine{display:none}}
/* Phones: the chips get the whole bar and swipe horizontally rather than wrap or clip. */
@media (max-width:599.98px){
  .mlt-ft__brand{display:none}
  .mlt-ft__links{display:none}
  .mlt-ft__ver{display:none}
  .mlt-ft{gap:10px}
  .mlt-ft__res{justify-content:flex-start;overflow-x:auto;overflow-y:hidden;scrollbar-width:none;
    -webkit-mask-image:linear-gradient(90deg,#000 88%,transparent);mask-image:linear-gradient(90deg,#000 88%,transparent)}
  .mlt-ft__res::-webkit-scrollbar{display:none}
  /* Drop the injected status group (after the flex-grow spacer): on a phone it duplicates the
     band status + dock dot, and it's what collides with the chips. Keep the metrics. */
  .mlt-ft__res .flex-grow-1,.mlt-ft__res .flex-grow-1~*{display:none}
  .mlt-ft__res .mud-typography{font-size:.7rem}
  .mlt-ft__res .mud-icon-root{font-size:1.05rem}

  /* No injected stats (dashboard, admin lists) = a bare phone dock, since chips are all this
     tier keeps. Give the space back to brand/links/version. */
  .mlt-ft:has(.mlt-ft__res:empty) .mlt-ft__brand{display:inline}
  .mlt-ft:has(.mlt-ft__res:empty) .mlt-ft__links{display:flex}
  .mlt-ft:has(.mlt-ft__res:empty) .mlt-ft__ver{display:inline}
  /* © stays hidden even here — with it the version clipped at the dock's right edge */
}

.mlt-tbe{display:inline-flex;align-items:center;gap:10px;margin-left:6px}
/* The health chip is its own coloured pill and self-gates — leave it unframed, just squared. */
.mlt-tbe__health .mud-chip{border-radius:9px;font-family:var(--mlt-font-mono);font-size:.68rem;letter-spacing:.08em}
.mlt-tbe__health:not(:has(.mud-chip)){display:none}
.mlt-tbe__pill{
  display:inline-flex;align-items:center;gap:8px;height:32px;padding:0 12px;border-radius:9px;
  border:1px solid var(--mud-palette-lines-default);
  background:rgba(var(--mud-palette-primary-rgb),.06);
}
.mlt-tbe__label{font-size:.62rem;opacity:.7}
@media (max-width:599.98px){.mlt-tbe__label{display:none}.mlt-tbe__pill{padding:0 8px}}
